class Solution:
    def countValidSubsets(self, parent: List[int], nums: List[int], k: int) -> int:
        n = len(parent)
        par = parent
        ans = 0
        for mask in range(1, 1 << n):
            s = 0
            ok = True
            for i in range(n):
                if mask >> i & 1:
                    s += nums[i]
                    if par[i] != -1 and (mask >> par[i]) & 1:
                        ok = False
                        break
            if ok and s % k == 0:
                ans += 1
        return ans

