class Solution {
public:
    int countValidSubsets(vector<int>& parent, vector<int>& nums, int k) {
        int n = parent.size(), ans = 0;
        for (int mask = 1; mask < (1 << n); mask++) {
            long long s = 0;
            bool ok = true;
            for (int i = 0; i < n && ok; i++)
                if (mask >> i & 1) {
                    s += nums[i];
                    if (parent[i] != -1 && (mask >> parent[i] & 1)) ok = false;
                }
            if (ok && s % k == 0) ans++;
        }
        return ans;
    }
};

