class Solution:
    def countValidSubsets(self, parent: List[int], nums: List[int], k: int) -> int:
        MOD = 10 ** 9 + 7
        n = len(parent)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[parent[i]].append(i)
        def dfs(u):
            acc = [0] * k
            acc[0] = 1
            for c in ch[u]:
                c0, c1 = dfs(c)
                na = [0] * k
                for r in range(k):
                    a = acc[r]
                    if a:
                        for t in range(k):
                            v = c0[t] + c1[t]
                            if v:
                                na[(r + t) % k] = (na[(r + t) % k] + a * v) % MOD
                acc = na
            d0 = acc[:]
            d1 = [0] * k
            s = nums[u] % k
            for r in range(k):
                d1[(r + s) % k] = acc[r]
            return d0, d1
        d0, d1 = dfs(0)
        return (d0[0] + d1[0] - 1) % MOD

