class Solution {
    int k;
    const long long MOD = 1e9 + 7;
    vector<vector<int>> ch;
    vector<int> nums_;
    pair<vector<long long>, vector<long long>> dfs(int u) {
        vector<long long> acc(k, 0);
        acc[0] = 1;
        for (int c : ch[u]) {
            auto [c0, c1] = dfs(c);
            vector<long long> na(k, 0);
            for (int r = 0; r < k; r++) {
                if (!acc[r]) continue;
                for (int t = 0; t < k; t++) {
                    long long v = c0[t] + c1[t];
                    if (v) na[(r + t) % k] = (na[(r + t) % k] + acc[r] * v) % MOD;
                }
            }
            acc = move(na);
        }
        vector<long long> d1(k, 0);
        int s = nums_[u] % k;
        for (int r = 0; r < k; r++) d1[(r + s) % k] = acc[r];
        return {acc, d1};
    }
public:
    int countValidSubsets(vector<int>& parent, vector<int>& nums, int k_) {
        k = k_;
        nums_ = nums;
        int n = parent.size();
        ch.assign(n, {});
        for (int i = 1; i < n; i++) ch[parent[i]].push_back(i);
        auto [d0, d1] = dfs(0);
        return (int)((d0[0] + d1[0] - 1 + MOD) % MOD);
    }
};

