class Solution {
    static final long MOD = 1_000_000_007L;
    int k;
    List<List<Integer>> ch;
    int[] nums;
    long[][] dfs(int u) {
        long[] acc = new long[k];
        acc[0] = 1;
        for (int c : ch.get(u)) {
            long[][] cd = dfs(c);
            long[] na = new long[k];
            for (int r = 0; r < k; r++) {
                if (acc[r] == 0) continue;
                for (int t = 0; t < k; t++) {
                    long v = cd[0][t] + cd[1][t];
                    if (v != 0) na[(r + t) % k] = (na[(r + t) % k] + acc[r] * v) % MOD;
                }
            }
            acc = na;
        }
        long[] d1 = new long[k];
        int s = nums[u] % k;
        for (int r = 0; r < k; r++) d1[(r + s) % k] = acc[r];
        return new long[][]{acc, d1};
    }
    public int countValidSubsets(int[] parent, int[] nums, int k) {
        this.k = k;
        this.nums = nums;
        int n = parent.length;
        ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(parent[i]).add(i);
        long[][] d = dfs(0);
        return (int)((d[0][0] + d[1][0] - 1 + MOD) % MOD);
    }
}

