                if (!acc[r]) continue;
                for (let t = 0; t < k; t++) {
                    const v = c0[t] + c1[t];
                    if (v) na[(r + t) % k] = (na[(r + t) % k] + acc[r] * v) % MOD;
                }
            }
            acc = na;
        }
        const d1 = new Array(k).fill(0);
        const s = nums[u] % k;
